# -*- coding: utf-8 -*-
from _e38_gen import t, body, MS, PH, AREA, DOD_QA, DOD_SEC

Q = dict(kind="Task", component="cross-cutting", phase=PH, milestone=MS, perspective="Test", parent="E38")
X = dict(kind="Task", component="cross-cutting", phase=PH, milestone=MS, perspective="Security", parent="E38")

t(**Q, key="E38-Q01", title="Black-box test plan for paper trading and demo/live parity",
  labels=["type/test", AREA, "priority/p1", "qa"], sprint="Sprint 18",
  priority="P1 High", risk="R9 Advice boundary", estimate=2, blocked_by=["E38-D06", "E38-K01"],
  body=body(
   ctx="`docs/plan/03-testing-strategy.md` requires a black-box test plan per feature, and `docs/plan/02-definition-of-ready-done.md` section 3.2 makes QA sign-off a hard gate for every Story. E38's risk profile is unusual: most of its acceptance criteria are *negative* (this must never happen), and negative requirements are exactly what ad hoc testing misses.\n\nThis ticket writes the plan before the stories land, so QA is testing against a specification rather than against whatever was built.",
   scope="- Author `qa/plans/E38-paper-parity.md` covering every E38 story: S01 demo integration, S02 switching, S03 the matcher, S04 chrome, S05 simulated results, S06 reset, S07 eligibility, S08 parity report.\n- Per story: preconditions, data setup, step-by-step cases, expected results, and explicit negative cases derived from each story's 'must never' criteria - cross-environment request refused, WS order entry on demo unreachable, reset absent in live, simulated results excluded from live analytics, no hotkey path to the switch.\n- A dedicated **environment-confusion charter**: an exploratory session specifically hunting any screen, panel, modal, floating window, toast, export or printed artefact that does not state its environment.\n- A dedicated **simulated-confusion charter**: hunting any surface where a paper figure could be mistaken for a real one, including exports, the journal and analytics.\n- A **state-transition matrix** for the environment switch: from each of (demo, live) x (armed, disarmed) x (algo running, idle) x (eligible, ineligible) x (stepped-up, not), the expected outcome.\n- Test-data setup instructions using the `CV_ENV=dev` seeds (`docs/plan/21-database-schema.md` seeds section: owner/manager/viewer, demo accounts, recorded BTCUSDT fixture) so any tester can reproduce the environment.\n- Entry/exit criteria for QA sign-off of the epic and the mapping from each plan case to the Gherkin scenario it verifies.",
   oos="- Executing the plan (E38-Q06) or automating it (E38-Q02).\n- Performance and chaos testing (E38-Q03, E38-Q04) and the a11y audit (E38-Q05), which have their own tickets.\n- Testing other epics' surfaces except where E38 badges them.",
   ac="```gherkin\nScenario: Every story has traceable coverage\n  Given the eight E38 stories and their Gherkin scenarios\n  When the plan is reviewed\n  Then every scenario maps to at least one numbered plan case, and the mapping table is part of the plan\n\nScenario: Negative requirements are explicitly cased\n  Given each 'must never' criterion in the epic\n  When the plan is reviewed\n  Then each has a case that actively attempts the forbidden action rather than merely observing the happy path\n\nScenario: The plan is executable by someone new\n  Given a tester who has not worked on E38\n  When they follow the setup and cases\n  Then they can execute every case without asking the author a question\n\nScenario: Exit criteria are objective\n  When QA sign-off is considered\n  Then the plan states the pass rate, open-defect thresholds and mandatory-case list required, with no subjective judgement\n```",
   tech="- Cases are numbered `E38-TC-nnn` and referenced by the automation in E38-Q02, so a failing automated test names the manual case it replaces.\n- Where a case cannot be automated, the plan says so explicitly and a Task is filed to automate it later (per `docs/plan/02-definition-of-ready-done.md` section 3.2).\n- The plan distinguishes cases that require a real demo account from those runnable against `CV_FEED=synthetic`, since CI cannot hold demo credentials (SR-140).",
   test="- The plan is itself reviewed by the Architect and one backend and one frontend engineer from E38, who confirm each negative case is actually reachable as written.\n- A dry-run of three representative cases validates the setup instructions before the plan is accepted.",
   sec="- The plan includes the abuse cases owned by E38-X02 by reference, so QA and Security are not testing the same ground twice or, worse, both assuming the other did.\n- Test data must never use real credentials; the plan states this as a precondition (SR-144).",
   a11y="- The plan references E38-Q05 for the accessibility audit rather than duplicating it, but includes keyboard-only execution of the environment switch as a functional case, because a pointer-only safety gate is a functional defect too.",
   perf="- The plan references budget #4 (order submit to ack p95 <300 ms on demo) as an observed-value case, with the measurement method, so functional testers notice a gross regression even before E38-Q03 runs.",
   obs="- Cases that should produce audit rows state which event name to verify, so QA validates observability rather than assuming it.",
   dod=DOD_QA,
   deps="- `blocked_by: E38-D06` (final designs and copy - the plan asserts exact strings), `E38-K01` (the confirmed parity differences the plan must verify are surfaced).",
   branch="`chore/e38-qa-plan`; PR size: docs-only.",
   refs="- `docs/plan/03-testing-strategy.md`\n- `docs/plan/02-definition-of-ready-done.md` section 3.2, section 8\n- `docs/plan/11-user-stories.md` section 21 PAPER\n- `docs/plan/21-database-schema.md` seeds section"))

t(**Q, key="E38-Q02", title="Automate the E38 end-to-end suite in Playwright web and Electron",
  labels=["type/test", AREA, "priority/p0", "qa"], sprint="Sprint 19",
  priority="P0 Critical", risk="R9 Advice boundary", estimate=3,
  blocked_by=["E38-Q01", "E38-S04", "E38-S05", "E38-S06", "E38-S07", "E38-S08"],
  body=body(
   ctx="The R3 quality gate requires Playwright coverage across web and Electron (`docs/plan/30-release-roadmap.md` section 7.4). E38's most important behaviours are cross-cutting and stateful - a switch that must tear down and rebuild every subscription, a badge that must appear on every panel including floating windows - which is precisely the class of behaviour unit tests cannot cover.\n\nElectron matters specifically here because detached/floating windows are separate BrowserWindows, and SCR-075 requires the band to repeat in every one of them.",
   scope="- Add to `tests/e2e/e38/` the following suites, each running in both the web and Electron projects:\n  1. **Demo order loop**: place, partial fill, amend, cancel on demo; assert state matches the orders and positions views and that the local mirror retains history.\n  2. **Environment switch**: demo to live with typed confirmation and step-up; assert phase progress is shown, order entry is blocked during the transition, every open pane re-badges, one-click trading is disarmed, and working demo orders are reported as not migrated.\n  3. **Switch refusals**: without step-up, with the flag off, without eligibility, and while an algo is running - each asserting the previous environment survives intact.\n  4. **Badge ubiquity**: enumerate every trading-capable panel including a floated Electron window and a maximised panel, asserting the environment appears in the visible text and in the accessible name.\n  5. **Cross-environment refusal**: issue a crafted API request from the browser context targeting a live account from a demo session; assert 403, no state change and an audit row visible in the security centre.\n  6. **Paper reset**: reset with open positions, confirm counts, assert the control is absent in live.\n  7. **Simulated results**: run a short replay with the paper matcher, open SCR-099, assert the disclosure block values, the default-off comparison, export, and promotion writing `simulated=true` journal rows.\n  8. **Parity report**: view the report, trigger a demo-only failure, assert a candidate item appears and the refusal deep-links to its row.\n  9. **Eligibility**: grant, acknowledge at next sign-in, revoke with open positions and assert reduce-only.\n- Wire all suites into the CI E2E job with the `CV_FEED=synthetic` profile plus recorded fixtures; cases requiring a real demo account are tagged and excluded from CI per SR-140, and run on the trading host as part of the release checklist.",
   oos="- Load and chaos testing (E38-Q03, E38-Q04).\n- The a11y audit (E38-Q05), though these suites assert accessible names where they are functionally load-bearing.\n- Other epics' E2E suites.",
   ac="```gherkin\nScenario: Every mandatory plan case is automated or explicitly deferred\n  Given the E38-TC case list from E38-Q01\n  When the suite is complete\n  Then each mandatory case is either automated with its case id referenced, or deferred with a filed automation Task\n\nScenario: Suites pass in both web and Electron\n  Given the Playwright web and Electron projects\n  When CI runs\n  Then all nine suites pass in both, including the floating-window badge assertion which only Electron can exercise\n\nScenario: The crafted cross-environment request is genuinely blocked\n  Given a demo session in the browser\n  When a live-targeting request is issued directly from the page context, bypassing the UI guard\n  Then the API returns 403, no order exists afterwards, and the audit row is visible in the admin security centre\n\nScenario: Tests fail for the right reason\n  Given a deliberately introduced regression removing a per-panel badge\n  When the suite runs\n  Then the badge-ubiquity suite fails and names the offending panel\n\nScenario: No credentials in CI\n  Given the CI configuration\n  When the suite runs\n  Then it uses synthetic feeds and fixtures only, and demo-credential-requiring cases are tagged out\n```",
   tech="- Use Playwright projects to share specs across web and Electron rather than duplicating them; only the launcher differs.\n- Deterministic setup: each suite seeds via the `CV_ENV=dev` seed path and tears down its own data, so suites can run in any order and in parallel.\n- Avoid timing flakiness on the switch suite by asserting on the `system` WS phase frames rather than sleeping.\n- Badge ubiquity is driven by a panel registry rather than a hardcoded list, so a newly added trading panel is automatically covered - a new panel without a badge should fail this suite the day it lands.\n- Accessible-name assertions use Playwright's accessibility snapshot, which is also the cheapest early warning for the E38-Q05 audit.",
   test="- The suite is the test artefact; its own reliability is verified by 20 consecutive green runs before it becomes a required check (flake budget zero for safety-critical suites).\n- Mutation check: the deliberately-introduced-regression scenario above is run once per suite to confirm each actually detects its target.",
   sec="- The crafted-request suite is an automated abuse case; it complements, and does not replace, E38-X02's manual review.\n- Test credentials are seed-generated fakes; SR-140 forbids real demo keys in CI and the suite configuration must make that structurally impossible (no secret referenced by the workflow).",
   a11y="- Accessible-name assertions are functional here (SCR-075 requires the environment in each panel's accessible name), so they live in this suite as well as in E38-Q05.",
   perf="- The suite records order submit-to-ack timings as an informational artefact; a gross regression against budget #4 fails a soft assertion so it is visible before the dedicated load test runs.",
   obs="- Suites assert the presence of the expected audit events (`session.environment_switched`, `trading.environment_mismatch_rejected`, `paper.balance_reset`, `journal.simulated_import`), turning observability into a tested contract rather than a hope.",
   dod=DOD_QA,
   deps="- `blocked_by: E38-Q01` (the plan being automated) and every E38 frontend story being merged and deployable.",
   branch="`test/e38-e2e`; PR size: split by suite - nine suites will exceed 400 LOC as one PR.",
   refs="- `docs/plan/03-testing-strategy.md`\n- `docs/plan/30-release-roadmap.md` section 7.4 quality gates\n- `qa/plans/E38-paper-parity.md` (from E38-Q01)\n- `docs/plan/04-security-program.md` SR-140"))

t(**Q, key="E38-Q03", title="Performance and load validation of the demo order path and paper matcher",
  labels=["type/test", AREA, "priority/p1", "qa", "perf"], sprint="Sprint 19",
  priority="P1 High", risk="R2 Render performance", estimate=2, blocked_by=["E38-S01", "E38-S03", "E38-S02"],
  body=body(
   ctx="Budget #4 in `docs/plan/06-performance-and-load-standard.md` - order submit to ack p95 <300 ms on demo - is a **hard R3 exit gate**, and E38-S01 is the story that owns the demo half of it. Budget #15 requires replay at up to 100x, which the paper matcher must not bottleneck.\n\nThe environment switch adds a budget of its own: it blocks order entry for its whole duration (SCR-074 states typically <=2 s), so a slow switch is a trading outage rather than a slow page.",
   scope="- k6 (or Locust) script `tests/load/e38_demo_orders.js`: sustained order submit/amend/cancel against the demo path at the per-UID rate budget, measuring submit-to-ack p50/p95/p99 separated into backend-internal and exchange RTT components (budget #4 excludes Bybit RTT from the backend-internal figure, per section 3.1).\n- Paper-matcher throughput benchmark: replay a recorded BTCUSDT day through the matcher, measuring matched-events per second and asserting the 20x-faster-than-real-time requirement from E38-S03 and the 100x replay ceiling of budget #15.\n- Environment-switch timing: measure the full transition (teardown, re-auth, resubscribe) at a realistic subscription count (10 symbols, multi-pane workspace), asserting p95 <=2 s and recording the per-phase breakdown so a regression is attributable.\n- Memory: assert the matcher stays within budget #8 (<=300 MB per actively-recorded symbol) during a full-day replay.\n- Frontend: assert an environment change does not exceed the frame budget (#1) - measure the render cost of re-badging every panel in a worst-case layout.\n- Record all results in `docs/perf/results/E38.md` with the reference-hardware profile stated (section 3.1) and compare against the budget table.",
   oos="- Chaos and failure-injection (E38-Q04).\n- Load testing other epics' paths (E34 owns fan-out load).\n- Tuning - this ticket measures and reports; a breach becomes a defect ticket against the owning story.",
   ac="```gherkin\nScenario: Demo order latency is measured against the hard gate\n  Given sustained order flow on the demo path\n  When the load script completes\n  Then submit-to-ack p95 is reported with backend-internal and exchange-RTT components separated, and compared against the 300 ms budget\n\nScenario: A breach becomes a defect, not a footnote\n  Given a measured p95 above the budget\n  When results are recorded\n  Then a defect ticket is filed against the owning story with the measurement attached, and the R3 exit gate is flagged as at risk\n\nScenario: The matcher sustains replay speed\n  Given a full recorded day\n  When replayed through the paper matcher\n  Then it matches at least 20x faster than real time and does not become the limiting factor at 100x replay\n\nScenario: The switch completes inside its window\n  Given a 10-symbol multi-pane workspace with full private subscriptions\n  When the environment is switched\n  Then p95 transition time is at or under 2 s, with a per-phase breakdown recorded\n\nScenario: Memory stays inside budget\n  Given a full-day replay through the matcher\n  When memory is sampled\n  Then per-symbol resident memory stays at or under 300 MB\n\nScenario: Re-badging does not drop frames\n  Given a worst-case layout with all trading panels open\n  When the environment changes\n  Then no frame exceeds the 16.6 ms budget as a direct result of re-badging\n```",
   tech="- Measurement methods follow `docs/plan/06-performance-and-load-standard.md` section 7 exactly; deviating would make the numbers incomparable with other epics' results.\n- Order-path load runs against a real demo account on the trading host, not in CI (SR-140); the matcher and frontend benchmarks run in CI against fixtures and become tracked regression gates.\n- Separate the exchange RTT component by timestamping at the adapter boundary, since budget #4's hard gate applies to the backend-internal portion and the Bybit RTT is explicitly an uncontrolled factor.\n- The matcher benchmark pins the `FillModelConfig` so a config change cannot silently flatter the numbers.",
   test="- The scripts are the artefact; they are self-verified by running against a deliberately throttled backend and confirming they detect the induced latency.\n- Results are re-run at the end of the sprint to confirm no late regression before the R3 gate.",
   sec="- Load scripts must not embed credentials; they read from the same encrypted store as the application (SR-004, SR-144).\n- Sustained order flow on demo must respect the per-UID rate governor (E34-T02) rather than bypassing it - the test measures the real path including its admission control.",
   a11y="N/A - measurement only. The re-badging frame-cost test protects users who rely on a responsive UI, but has no direct a11y assertion.",
   perf="- This ticket *is* the performance work: budgets #1, #4, #8, #13 and #15 from `docs/plan/06-performance-and-load-standard.md`.",
   obs="- Results feed the Grafana perf dashboard; the matcher throughput and switch duration become tracked metrics with regression alerts, not one-off measurements.",
   dod=DOD_QA,
   deps="- `blocked_by: E38-S01` (demo order path), `E38-S03` (matcher), `E38-S02` (switch orchestration to time).",
   branch="`test/e38-perf`; PR size: scripts plus results doc.",
   refs="- `docs/plan/06-performance-and-load-standard.md` budgets #1, #4, #8, #13, #15; sections 3.1, 7\n- `docs/plan/30-release-roadmap.md` section 7.3 exit criterion 11\n- `docs/plan/14-screens-catalogue.md` SCR-074 performance note"))

t(**Q, key="E38-Q04", title="Chaos scenarios for environment switching and paper state recovery",
  labels=["type/test", AREA, "priority/p1", "qa"], sprint="Sprint 19",
  priority="P1 High", risk="R11 Alert reliability", estimate=2, blocked_by=["E38-S02", "E38-S03", "E38-S01"],
  body=body(
   ctx="The R3 chaos gate (`docs/plan/30-release-roadmap.md` section 7.4) requires that WS kill, backend restart and Postgres failover all resume to a correct, reconciled state. E38 adds two specifically fragile moments: the environment transition, which deliberately tears down and rebuilds every private subscription, and the paper matcher's in-memory state, which must survive a restart without inventing or losing simulated positions.\n\nSCR-074's requirement that 'a half-switched state is never reachable' is exactly the kind of claim only fault injection can test.",
   scope="- Scenario 1: **backend restart mid-switch** at each phase boundary (after teardown, after re-auth, after partial resubscribe) - assert the session resolves to exactly one environment with consistent subscriptions and that the UI reflects it, never a mixed state.\n- Scenario 2: **WS disconnect during a demo order's lifetime** - assert reconciliation against `GET /v5/order/realtime` restores exact state with no duplicate submission and no lost fill.\n- Scenario 3: **backend restart with open simulated positions and resting simulated orders** - assert the `PaperLedger` and queue estimates recover from Postgres with no ghost orders and no duplicated fills.\n- Scenario 4: **Postgres unavailable during a paper reset** - assert the transaction aborts cleanly and the pre-reset state is fully intact (E38-S06's atomicity criterion under real failure rather than an injected exception).\n- Scenario 5: **audit writer unavailable during a cross-environment refusal** - assert the request still fails closed (refused), because failing open would trade an audit gap for a safety breach.\n- Scenario 6: **clock skew** between backend and exchange beyond the 1000 ms incident threshold during a demo order - assert the condition is detected and surfaced rather than silently producing mis-sequenced state.\n- Scenario 7: **demo private WS flapping** during a switch - assert the transition either completes or rolls back, never stalls indefinitely, and that a stall has a timeout with a stated outcome.\n- Record results in `docs/chaos/results/E38.md` with the injection method for each scenario so they are repeatable each release.",
   oos="- Fan-out and algo chaos (E34, E33 own theirs).\n- Infrastructure-level failover testing of Postgres itself (E45).\n- Performance measurement (E38-Q03).",
   ac="```gherkin\nScenario: No half-switched state survives a restart\n  Given the backend is killed at each phase boundary of an environment switch\n  When it restarts\n  Then the session resolves to exactly one environment with a consistent subscription set, and the UI reflects that environment truthfully\n\nScenario: Paper state recovers without ghosts\n  Given open simulated positions and resting simulated orders\n  When the backend restarts\n  Then the ledger, positions and resting orders with their queue estimates are restored from Postgres, with no duplicated fill and no order that no longer exists\n\nScenario: Reset is atomic under real database failure\n  Given Postgres becomes unavailable mid-reset\n  When the operation fails\n  Then the pre-reset balance, positions and orders are all intact and the failure is reported to the user\n\nScenario: Refusals fail closed without the audit writer\n  Given the audit writer is unavailable\n  When a cross-environment request is made\n  Then it is still refused, and the audit failure is itself alerted\n\nScenario: A stalled switch resolves rather than hanging\n  Given the demo private WS flaps during a transition\n  When the configured timeout elapses\n  Then the transition rolls back to the previous environment with a stated reason, and order entry is unblocked\n\nScenario: Clock skew is detected\n  Given backend-to-exchange clock offset exceeds one second\n  When a demo order is placed\n  Then the condition is surfaced as an incident rather than silently accepted\n```",
   tech="- Injection via the project's existing chaos harness (toxiproxy for network faults, container kill for restarts, a fault-injection hook for the audit writer), documented per scenario so the suite is repeatable by anyone.\n- Each scenario asserts on **observable state after recovery**, not on log lines, so the test is about correctness rather than implementation detail.\n- Phase-boundary restarts are driven by pausing at the `system` phase frames E38-S02 emits, which makes the injection points precise rather than timing-based.\n- Scenarios 3 and 4 need a seeded matcher state fixture; build it once and share it with E38-Q02.",
   test="- The scenarios are the test artefact. Each must be demonstrated to fail against a deliberately broken build (e.g. a matcher that rebuilds state from memory only), proving the scenario has teeth.\n- Run as part of the release checklist, not on every PR, given their runtime.",
   sec="- Scenario 5 is a security-relevant chaos case: fail-closed behaviour under audit-writer failure is a control, and its verification is shared with E38-X02.\n- No real credentials are used; the demo-dependent scenarios run on the trading host per SR-140.",
   a11y="- Scenario 7 includes verifying the UI communicates the stalled/rolled-back state accessibly (announced, not merely visual), because a silent stall during a blocked-order-entry window is dangerous.",
   perf="- Record recovery times per scenario; a restart that takes minutes to rebuild matcher state is a defect even if it is eventually correct.",
   obs="- Each scenario asserts that the expected alert fires (WS disconnect with open orders, audit-writer failure, clock skew incident) - verifying the alerting path at the same time as the recovery path.",
   dod=DOD_QA,
   deps="- `blocked_by: E38-S02` (switch orchestration and rollback), `E38-S03` (matcher persistence), `E38-S01` (demo order path and reconciliation).",
   branch="`test/e38-chaos`; PR size: scenarios plus harness config plus results doc.",
   refs="- `docs/plan/30-release-roadmap.md` section 7.4 chaos gate\n- `docs/plan/14-screens-catalogue.md` SCR-074 ('a half-switched state is never reachable')\n- `docs/plan/03-testing-strategy.md`\n- `docs/plan/24-internal-schemas.md` section 12 matcher state"))

t(**Q, key="E38-Q05", title="Accessibility audit of every E38 surface with screen-reader passes",
  labels=["type/test", AREA, "priority/p1", "qa", "a11y"], sprint="Sprint 19",
  priority="P1 High", risk="R5 Scope", estimate=2,
  blocked_by=["E38-S04", "E38-S05", "E38-S06", "E38-S07", "E38-S08", "E38-D05"],
  body=body(
   ctx="`docs/plan/05-accessibility-standard.md` mandates WCAG 2.2 AA with axe-core in CI plus manual screen-reader passes, and there is explicitly no exception for owner/admin screens (`docs/plan/02-definition-of-ready-done.md` section 8).\n\nE38 is a hard case: the environment distinction must survive colour blindness and greyscale; the band repeats on every panel and must not create an announcement storm; SCR-099's charts each need a table alternative; and the reset confirmation is a destructive dialog whose counts must be announced.",
   scope="- axe-core automated runs against SCR-074 (modal open, each state), SCR-075 (shell in both environments, with a modal open, in a floating Electron window), SCR-079 reset section incl. the open confirmation, SCR-099 incl. table alternatives and comparison-on, SCR-122 eligibility section, SCR-137 parity section - wired as CI checks, not one-off runs.\n- Manual screen-reader passes with **NVDA on Windows** (the primary target given the Electron shell) and a secondary pass with the platform reader in the browser build: full keyboard-only operation of the switch flow, the reset confirmation, the results drawer and the parity table.\n- Verify against the E38-D05 annotation layer specifically: the band is announced on demand but does not re-announce per panel render; the post-switch banner announces once assertively; focus moves into and returns from every dialog; the typed-confirm error is announced and associated.\n- Colour-independence verification on the built app: greyscale plus deuteranopia, protanopia and tritanopia simulations for the environment treatments and the simulated badge.\n- Contrast re-measurement on the built app against the D05 recorded values.\n- Reduced-motion verification: the chrome transition degrades to an instant swap.\n- File every finding as a Bug with the WCAG success criterion referenced; blocking findings prevent epic sign-off.",
   oos="- Design-time annotation review (E38-D05, already done).\n- Design QA of visual fidelity (E38-D07).\n- Auditing other epics' panels, except to confirm the E38 badge they host is accessible.",
   ac="```gherkin\nScenario: axe-core is green and wired into CI\n  Given every E38 surface and state\n  When axe-core runs\n  Then there are zero violations, and the checks run on every PR rather than only during this audit\n\nScenario: The switch is fully keyboard operable\n  Given a keyboard-only user with a screen reader\n  When they switch environments\n  Then the entire path from band to typed confirmation to step-up to completion is operable, with visible focus at every step and the outcome announced\n\nScenario: No announcement storm from repeated badges\n  Given a workspace with many trading panels\n  When a panel re-renders\n  Then the environment is not re-announced for each panel\n\nScenario: Destructive counts are announced\n  Given a reset with open positions\n  When the confirmation opens\n  Then the number of positions and orders to be discarded is announced, and focus does not default to the destructive button\n\nScenario: Charts have usable table alternatives\n  Given the SCR-099 equity curve and R distribution\n  When navigating with a screen reader only\n  Then each has a reachable table alternative conveying the same information\n\nScenario: Environment survives colour-vision simulation on the built app\n  Given the running application\n  When rendered in greyscale and the three colour-vision simulations\n  Then DEMO and LIVE remain unambiguous, and any failure is filed as priority p0 with the security label\n```",
   tech="- axe-core runs are per-state, not per-page: a modal's states are separate assertions, since most violations hide in states the default render never reaches.\n- Screen-reader passes are recorded (screen plus audio) so findings are reviewable without re-running the session.\n- Colour-vision simulation on the built app uses a browser-level filter rather than a design tool, because token resolution at runtime is what actually matters.\n- Findings reference both the WCAG criterion and the D05 annotation that specified the intended behaviour, so it is clear whether the build or the spec was wrong.",
   test="- The audit is the test artefact; its outputs are the axe CI checks (permanent) and the findings list (point-in-time).\n- Re-verification of fixed findings is part of this ticket.",
   sec="- An ambiguous or absent environment indication found during the audit is filed as `priority/p0-critical` with the `security` label - it defeats the user-facing half of SR-040a regardless of whether the cause is an accessibility defect.",
   a11y="- This ticket *is* the accessibility verification: WCAG 2.2 AA across 1.3.1, 1.4.1, 1.4.3, 1.4.11, 1.4.12, 2.1.1, 2.1.2, 2.4.3, 2.4.7, 2.4.11, 3.2.2, 3.3.1, 3.3.2, 4.1.2, 4.1.3.",
   perf="- Confirm the announcement strategy does not cause a render storm (cross-check with E38-Q03's re-badging frame measurement).",
   obs="N/A - though the audit confirms that status announcements correspond to real state changes rather than to arbitrary re-renders.",
   dod=DOD_QA,
   deps="- `blocked_by`: every E38 UI story plus `E38-D05` (the specification the audit measures against).",
   branch="`test/e38-a11y-audit`; PR size: axe CI config plus findings doc.",
   refs="- `docs/plan/05-accessibility-standard.md`\n- `docs/plan/02-definition-of-ready-done.md` section 8\n- `docs/plan/14-screens-catalogue.md` SCR-074, SCR-075, SCR-079, SCR-099, SCR-122, SCR-137 a11y notes"))

t(**Q, key="E38-Q06", title="Execute the E38 regression pack, exploratory charters and QA sign-off",
  labels=["type/test", AREA, "priority/p0", "qa"], sprint="Sprint 19",
  priority="P0 Critical", risk="R9 Advice boundary", estimate=2,
  blocked_by=["E38-Q02", "E38-Q03", "E38-Q04", "E38-Q05"],
  body=body(
   ctx="`docs/plan/02-definition-of-ready-done.md` section 2.2 requires an epic-level regression and exploratory pass, not merely the sum of child-ticket QA. E38 is the epic whose failure mode is a trader acting on a wrong belief about their environment or their results, so the final pass is deliberately adversarial rather than confirmatory.\n\nThis ticket also produces the QA input to the R3 PRR and the 7-day soak that closes the train on 2027-06-18.",
   scope="- Execute the full `qa/plans/E38-paper-parity.md` case list against the staging (demo) build, recording pass/fail per case.\n- Run the two exploratory charters from E38-Q01 timeboxed to 90 minutes each: the **environment-confusion charter** (find any surface not stating its environment) and the **simulated-confusion charter** (find any surface where a paper figure could pass for a real one), including exports, printed views, notification toasts, the notification centre, OS notifications from Electron, and any webhook payload.\n- Assemble the **E38 regression pack**: the subset of cases that must run before every subsequent release, chosen for the irreversibility of what they protect (cross-environment refusal, badge ubiquity, reset-hidden-in-live, simulated exclusion from analytics).\n- Verify epic-level exit criteria: every child ticket Done, no open P0/P1 against E38 scope, coverage floors held on `cv/paper/` and the touched frontend packages, and the E38-D07 design-QA and E38-Q05 a11y findings closed.\n- Contribute E38's section to the R3 PRR pack and confirm the E38 regression pack is included in the 7-day soak's monitoring checklist.\n- Post the QA sign-off comment with pass/fail per scenario and any recorded deviation.",
   oos="- Writing the plan (E38-Q01) or automating it (E38-Q02).\n- Fixing defects found - those are Bug tickets against the owning stories.\n- The soak itself (an R3-level activity, `q09` in the roadmap), to which this contributes the checklist.",
   ac="```gherkin\nScenario: The plan is fully executed\n  Given the E38 test plan\n  When execution completes\n  Then every case has a recorded pass or fail, with evidence attached for each failure\n\nScenario: Both charters are executed and reported\n  Given the environment-confusion and simulated-confusion charters\n  When each 90-minute session completes\n  Then a session report lists coverage, findings and any area left unexplored\n\nScenario: Exports and notifications are covered\n  Given CSV and Parquet exports, toasts, the notification centre, OS notifications and webhook payloads\n  When the charters run\n  Then each is checked for environment and simulated labelling, and any omission is filed\n\nScenario: Sign-off is blocked by an open P0 or P1\n  Given an open P0 or P1 defect in E38 scope\n  When sign-off is attempted\n  Then it is refused until the defect is closed or explicitly accepted by the Owner with a recorded rationale\n\nScenario: The regression pack is defined and adopted\n  When this ticket completes\n  Then the E38 regression pack is committed, named in the release checklist, and scheduled within the R3 soak monitoring\n```",
   tech="- Exploratory sessions use session-based test management: charter, timebox, notes, findings, coverage statement - so the sessions are auditable rather than anecdotal.\n- Execution happens on staging (demo) per `docs/plan/02-definition-of-ready-done.md` section 8; never against live.\n- The regression pack is defined as a Playwright tag so it is runnable as one command, not a document someone must re-read.",
   test="- This ticket is execution. Its quality control is that every failure is reproducible from the recorded evidence by someone else.",
   sec="- Any finding with a safety or security implication is escalated immediately to E38-X03 rather than waiting for sign-off, and is labelled `security`.\n- Exploratory testing must not use real credentials or funded accounts (SR-144).",
   a11y="- The charters include a keyboard-only pass through the primary flows; a11y findings are cross-filed with E38-Q05 rather than duplicated.",
   perf="- Confirms E38-Q03's recorded numbers are still representative at the end of the sprint; a late regression is filed before the R3 gate rather than discovered during the soak.",
   obs="- Verifies the E38 dashboard panels and alerts exist and fire: capability refusals, environment rejections, switch failures, divergence breaches, paper resets.",
   dod=DOD_QA,
   deps="- `blocked_by`: all other E38 QA tickets, since this is the consolidating pass.",
   branch="`test/e38-signoff` (regression pack tag plus reports); PR size: docs and config.",
   refs="- `docs/plan/02-definition-of-ready-done.md` section 2.2, section 8\n- `docs/plan/07-release-and-prr.md` PRR gate\n- `docs/plan/30-release-roadmap.md` section 7.3 exit criteria, `q09` soak\n- `qa/plans/E38-paper-parity.md`"))

t(**X, key="E38-X01", title="STRIDE threat model for paper trading and demo/live separation",
  labels=["type/security", AREA, "priority/p0", "security"], sprint="Sprint 17",
  priority="P0 Critical", risk="R9 Advice boundary", estimate=2, blocked_by=["E38-K01", "E29", "E27"],
  body=body(
   ctx="`docs/plan/04-security-program.md` requires a STRIDE threat model per epic, and `docs/plan/02-definition-of-ready-done.md` section 2.1 makes it default-on for any epic touching the OMS. E38 sits on top of the most dangerous boundary in the product: the one between practice and real money.\n\nThe security program already names two E38-relevant threats - **W9** (code assuming WS order entry exists on demo, causing unplaced or duplicated orders) and **W10** (demo and live endpoints mixed in one session) - with SR-040a as the control. This ticket completes the model before the implementation stories start, so the controls are designed in rather than retrofitted.",
   scope="- Produce `docs/security/threat-models/E38-paper-trading.md` with a data-flow diagram covering: the session's environment attribute, the environment switch, the adapter's per-environment clients, the isolation middleware, the paper matcher, the paper ledger, eligibility grants, and the parity report.\n- STRIDE enumeration per element and per flow, with at minimum:\n  - **Spoofing**: a UI claiming demo while the session is live; a forged `system` WS frame re-badging panels.\n  - **Tampering**: a crafted account id targeting live from a demo session; mutating an adapter base URL at runtime; modifying the parity data file to hide a known difference.\n  - **Repudiation**: an environment switch or a paper reset with no audit trail; an audit writer failure allowing an unrecorded action.\n  - **Information disclosure**: a not-permitted message revealing other users' live grants; raw exchange payloads stored in candidate parity items; demo keys in logs.\n  - **Denial of service**: switch-flapping to disrupt subscriptions; unbounded candidate-parity-item growth from a repeating error.\n  - **Elevation of privilege**: a manager self-granting live eligibility; acting on a live grant before acknowledgement; the paper matcher reaching the network and placing a real order.\n- Risk rating (likelihood x impact) per threat, with the control, the owning ticket and the verifying test named for each - a threat with no named test is not considered mitigated.\n- Explicit abuse-case list handed to E38-X02 and cross-referenced into `qa/plans/E38-paper-parity.md`.\n- Update `docs/plan/32-risk-register.md` with any new risk and its owner.",
   oos="- Executing the abuse cases (E38-X02) or the final review (E38-X03).\n- Threat-modelling the OMS, key vault or fan-out (E29, E27, E34 own theirs) - E38's model references them as trust boundaries rather than re-analysing them.\n- Pen-testing, which is an R4 activity (E43).",
   ac="```gherkin\nScenario: Every element and flow is enumerated\n  Given the E38 data-flow diagram\n  When the model is reviewed\n  Then every element and flow has a STRIDE pass recorded, with 'not applicable' stated explicitly and justified rather than left blank\n\nScenario: Every threat has a control and a test\n  Given the enumerated threats\n  When the model is complete\n  Then each names its control, the ticket implementing it, and the specific test that verifies it\n\nScenario: Critical and High threats are scheduled\n  Given a threat rated Critical or High\n  When the model is signed off\n  Then its control is implemented by a ticket inside this epic's sprint window, or the risk is explicitly accepted by the Owner in writing\n\nScenario: The known security-program threats are carried forward\n  Given W9 and W10 from docs/plan/04-security-program.md\n  When the model is reviewed\n  Then both appear with SR-040a as their control and E38-T01 as the implementing ticket, with their verifying tests named\n\nScenario: The simulator-reaches-the-network threat is treated as Critical\n  Given the paper matcher\n  When the elevation-of-privilege analysis is reviewed\n  Then the possibility of a simulated order reaching the exchange is rated Critical with the structural no-transport test named as its control\n```",
   tech="- Use the project's existing threat-model template so findings aggregate across epics for the R4 pen-test scope.\n- Trust boundaries to draw explicitly: browser/backend, backend/exchange (per environment), backend/Postgres, and the user/owner privilege boundary for eligibility.\n- The model must state which controls are **structural** (impossible by construction, e.g. separate client instances) versus **enforced** (checked at runtime, e.g. the isolation middleware) - structural controls need less ongoing verification and this distinction shapes the regression pack.",
   test="- The model is reviewed by the Security engineer and the Architect; review sign-off is the acceptance.\n- Its output becomes test cases in E38-X02, E38-Q01 and E38-Q04, so the model's quality is measured by whether those tickets can be written from it without further analysis.",
   sec="- This ticket *is* the security analysis. It must be completed before E38-T01/T02 merge, so the controls those tickets implement are the ones the model asked for.\n- Classification of data touched: session attributes, account identifiers, API credentials (by reference only), financial simulation data.",
   a11y="N/A - analysis artefact. One note is in scope: the model should record that an inaccessible environment indicator is a security failure, not only an a11y one, since a user who cannot perceive the indicator cannot verify their environment.",
   perf="N/A - though the model should note that any control added to the per-order path must respect budget #4, so controls are placed at session or startup level where possible rather than per request.",
   obs="- The model specifies the audit events and alerts each control requires, which E38-T02, S02, S06 and S07 then implement - so observability is derived from the threat analysis rather than invented per ticket.",
   dod=DOD_SEC,
   deps="- `blocked_by: E38-K01` (the real capability differences to model against), `E29` and `E27` (the OMS and key vault trust boundaries the model references).",
   branch="`chore/e38-threat-model`; PR size: docs-only.",
   refs="- `docs/plan/04-security-program.md` (threats W9, W10; SR-040a, SR-043, SR-119)\n- `docs/plan/02-definition-of-ready-done.md` section 2.1\n- `docs/plan/24-internal-schemas.md` section 15.2 RBAC 4-tuple\n- `docs/plan/32-risk-register.md`"))

t(**X, key="E38-X02", title="Abuse cases, permission checks and SAST rules for the environment boundary",
  labels=["type/security", AREA, "priority/p0", "security"], sprint="Sprint 19",
  priority="P0 Critical", risk="R9 Advice boundary", estimate=2,
  blocked_by=["E38-X01", "E38-T02", "E38-S02", "E38-S03", "E38-S07"],
  body=body(
   ctx="E38-X01 enumerated the threats; this ticket attacks the built system and turns the durable findings into automated rules. `docs/plan/02-definition-of-ready-done.md` section 8 requires a manual abuse-case check for anything touching RBAC, and the R3 quality gate requires a targeted abuse-case review of privilege escalation before the train closes.\n\nThe specific claims under attack are the ones the epic's safety rests on: that no demo session can reach live, that no simulated order can reach the exchange, and that no manager can grant themselves live access.",
   scope="- Execute the abuse-case list from E38-X01 against the staging build, at minimum:\n  1. Craft a live-targeting request from a demo session via every trading route (driven from the route list in E38-T02), including direct API calls bypassing the UI entirely.\n  2. Attempt to switch to live without step-up, with an expired elevation, with the `live_trading` flag off, and by replaying a previously successful switch request.\n  3. Attempt to act on a live grant before acknowledgement.\n  4. Attempt self-granting of live eligibility as a manager, and via a crafted `PUT /users/{userId}/account-access` payload targeting one's own user id.\n  5. Attempt to create and to submit a mixed-environment trade group.\n  6. Attempt to make the paper matcher perform a network call (dependency injection, config override, monkeypatch-style manipulation of the adapter routing).\n  7. Attempt to reset a live account's balance via the paper-reset endpoint.\n  8. Attempt to read another user's grants through the not-permitted message, the parity report or an error body.\n  9. Attempt to flood candidate parity items to exhaust storage.\n- Verify for each: refusal, no state change, an audit row of the right severity, and no information leaked in the response.\n- Commit durable detections: Semgrep rules forbidding (a) a Bybit hostname outside `capabilities.py`, (b) a trading route handler without the environment dependency, (c) an HTTP/WS client import inside `cv/paper/`; plus a ZAP/DAST profile exercising the cross-environment routes.\n- Run SCA and secrets scanning over the new code paths and triage findings.",
   oos="- The threat model itself (E38-X01) and the final review (E38-X03).\n- Pen-testing (E43, an R4 activity) - this is internal abuse-case testing, deliberately narrower.\n- Load-based denial of service beyond the candidate-item flood case (E38-Q03 covers capacity).",
   ac="```gherkin\nScenario: Every abuse case is executed and recorded\n  Given the abuse-case list from the threat model\n  When testing completes\n  Then each case has a recorded outcome with evidence, and any success is filed as a priority p0 security defect\n\nScenario: Cross-environment attempts are refused on every route\n  Given the full trading route list\n  When a live-targeting request is crafted from a demo session on each\n  Then every route refuses with 403, changes no state, and writes a high-severity audit row\n\nScenario: The simulator cannot be made to reach the network\n  Given attempts to route the paper matcher through a real transport\n  When each is tried\n  Then none succeeds, and the structural Semgrep rule prevents the import that would enable it\n\nScenario: Self-granting is impossible\n  Given a manager account\n  When eligibility self-grant is attempted directly against the API\n  Then it is refused and audited, and the attempt does not partially apply\n\nScenario: Durable rules are committed and run in CI\n  When this ticket completes\n  Then the three Semgrep rules and the ZAP profile are committed and executing in CI, failing the build on violation\n\nScenario: A replayed switch request does not re-switch\n  Given a captured successful switch request\n  When it is replayed after the elevation expires\n  Then it is refused rather than honoured\n```",
   tech="- Testing is black-box against staging plus white-box review of the isolation middleware, the adapter routing and the eligibility derivation - the combination matters because a route can pass black-box testing while having the guard attached in a way a refactor would silently drop.\n- The route-list-driven approach means this test automatically covers routes added after E38-T02 was written, as long as the OpenAPI document is the source.\n- Semgrep rules are written to fail on the *pattern*, not on a filename allowlist, so moving a file does not defeat them.\n- Evidence for each case: request, response, database state before and after, and the audit row (or its absence, which is itself a finding).",
   test="- The abuse cases are the test artefact. Each durable rule must be demonstrated to fire against a deliberately introduced violation before it is accepted.\n- Findings are re-verified after fixes within this ticket.",
   sec="- This ticket *is* the security testing: SAST (Semgrep/Bandit/CodeQL), DAST (ZAP), SCA (pip-audit/npm audit) and secrets scanning over E38's code, plus manual abuse-case execution per `docs/plan/02-definition-of-ready-done.md` section 8.\n- Any successful abuse case is a `priority/p0-critical` defect that blocks the R3 gate, not a backlog item.",
   a11y="N/A - security testing. One cross-check: confirm that refusal messages remain accessible (associated with their control, announced) while not disclosing more than they should.",
   perf="- The candidate-parity-item flood case is also a capacity check: confirm deduplication bounds growth, so a repeating demo error cannot fill the disk.",
   obs="- Verify every refusal produces the audit event and metric the threat model specified, at the right severity; a missing audit row on a refused abuse attempt is itself a finding.",
   dod=DOD_SEC,
   deps="- `blocked_by: E38-X01` (the case list), `E38-T02`, `E38-S02`, `E38-S03`, `E38-S07` (the controls under attack must exist).",
   branch="`test/e38-abuse-cases`; PR size: rules plus DAST profile plus findings doc.",
   refs="- `docs/plan/04-security-program.md` SR-040a, SR-119, SR-140, section 7 RBAC\n- `docs/plan/02-definition-of-ready-done.md` section 8\n- `docs/security/threat-models/E38-paper-trading.md` (from E38-X01)\n- `docs/plan/30-release-roadmap.md` section 7.4 security gate"))

t(**X, key="E38-X03", title="Security review and sign-off of the shipped paper-trading and parity surfaces",
  labels=["type/security", AREA, "priority/p0", "security"], sprint="Sprint 19",
  priority="P0 Critical", risk="R9 Advice boundary", estimate=1,
  blocked_by=["E38-X02", "E38-Q06", "E38-S08"],
  body=body(
   ctx="`docs/plan/30-release-roadmap.md` section 7.4 requires all Critical and High STRIDE findings closed before the R3 train ends, and E44 (live enablement) depends on E38 - the roadmap dependency graph has `E38 --> E44`. Whatever E38 leaves unresolved becomes a live-money problem in R4.\n\nThis is the closing gate: confirm every control the threat model asked for exists, works, and is verified by a test that will keep running.",
   scope="- Verify each control from `docs/security/threat-models/E38-paper-trading.md` is implemented, with its verifying test present and passing: the capability matrix, the isolation middleware and its route-coverage gate, the switch's step-up and flag gates, eligibility enforcement and the acknowledgement gate, the paper matcher's structural no-transport guarantee, the reset's env refusal, and the parity report's non-disclosure of raw payloads.\n- Confirm every finding from E38-X02 is fixed or has a written Owner-accepted risk with an expiry date.\n- Confirm SAST, DAST, SCA and secrets scanning are clean or triaged on all E38 paths, and that the three Semgrep rules plus the ZAP profile are running as required checks.\n- Confirm audit coverage: every action the threat model marked as needing non-repudiation writes an audit row of the specified severity, verified by executing each action and inspecting the log.\n- Produce the **E38 input to the R4 live-enablement gate**: a written statement of what E38 guarantees about environment separation, what it explicitly does not guarantee, and which assumptions E44 must re-verify before the flag is turned on.\n- Post the Security engineer sign-off comment required by `docs/plan/02-definition-of-ready-done.md`, and update `docs/plan/32-risk-register.md`.",
   oos="- New security testing (E38-X02 did that).\n- The R4 pen-test (E43) and the live-enablement gate itself (E44) - this produces input to them.\n- Other epics' sign-offs.",
   ac="```gherkin\nScenario: Every control is verified present and effective\n  Given the threat model's control list\n  When the review completes\n  Then each control is confirmed implemented with a named passing test, or is recorded as an accepted risk with Owner sign-off and an expiry date\n\nScenario: No Critical or High finding remains open\n  Given the findings from E38-X02 and E38-Q06\n  When sign-off is considered\n  Then no Critical or High finding is open, and the epic cannot be marked Done while one is\n\nScenario: Durable gates are actually required checks\n  Given the Semgrep rules, the route-coverage test and the ZAP profile\n  When the branch protection configuration is inspected\n  Then each is a required check, so a future PR cannot merge past them\n\nScenario: Audit coverage is verified by execution\n  Given each action requiring non-repudiation\n  When it is performed on staging\n  Then the corresponding audit row exists at the specified severity, verified by inspection rather than by reading the code\n\nScenario: The R4 handover statement exists\n  When this ticket completes\n  Then a written statement of E38's guarantees, non-guarantees and the assumptions E44 must re-verify is committed and linked from the E44 epic\n```",
   tech="- The review is evidence-based: for each control, the reviewer records the test name and the CI run in which it passed, not merely a code reference, because a test that exists but does not run is not a control.\n- The 'non-guarantees' section of the R4 statement is the most valuable output: it should name explicitly, for example, that E38 proves separation under tested conditions on demo and that live behaviour is re-verified by E44 and E43's pen-test.\n- Cross-check the structural-versus-enforced control classification from E38-X01: structural controls should have a compile-time or import-time test, enforced controls a runtime test.",
   test="- No new testing; verification of existing test evidence. Any control found without a verifying test causes a Task to be filed and blocks sign-off until it exists.",
   sec="- This ticket *is* the sign-off gate required by `docs/plan/02-definition-of-ready-done.md` section 2.2 and section 8, and by the R3 quality gate.\n- It must be performed by the Security engineer, not by the implementing engineers.",
   a11y="- Confirms that E38-Q05's environment-indicator findings, which have a security dimension, are closed - an imperceptible environment indicator is a security control failure.",
   perf="- Confirms that no control was weakened for performance reasons during implementation; any such trade-off must appear as an accepted risk rather than as an undocumented change.",
   obs="- Confirms the security-relevant metrics and alerts exist and are wired to a destination: capability refusals, environment rejections, switch failures, refused resets, live-eligibility changes.",
   dod=DOD_SEC,
   deps="- `blocked_by: E38-X02` (findings to close), `E38-Q06` (QA sign-off and its escalated findings), `E38-S08` (the parity report, which is part of the R4 handover evidence).\n- Feeds `E44` live-enablement gating and `E43` pen-test scoping.",
   branch="`chore/e38-security-signoff`; PR size: docs-only.",
   refs="- `docs/plan/30-release-roadmap.md` section 7.4 security gate, dependency `E38 --> E44`\n- `docs/plan/02-definition-of-ready-done.md` section 2.2, section 8\n- `docs/security/threat-models/E38-paper-trading.md`\n- `docs/plan/04-security-program.md`\n- `docs/plan/32-risk-register.md`"))

t(**dict(kind="Chore", component="docs", phase=PH, milestone=MS, perspective="Architecture", parent="E38"),
  key="E38-T04", title="Reconcile plan docs and ADRs with the shipped paper and parity behaviour",
  labels=["type/chore", AREA, "priority/p2"], sprint="Sprint 19",
  priority="P2 Medium", risk="None", estimate=1,
  blocked_by=["E38-S03", "E38-S08", "E38-T03"],
  body=body(
   ctx="`docs/plan/02-definition-of-ready-done.md` section 2.2 requires that the plan docs reflect final shipped behaviour, not the original proposal, wherever they diverged. E38 touches unusually normative documents - `docs/plan/24-internal-schemas.md` section 12 specifies the matcher field by field - so divergence between doc and code here is more damaging than usual: E44 and E43 will read these documents as truth when gating live enablement.",
   scope="- Reconcile `docs/plan/24-internal-schemas.md` section 12 (paper matcher) with the shipped `FillModelConfig`, queue model, fee, funding and margin implementations; correct any default, formula or behaviour that changed during implementation, and mark anything deliberately not implemented in R3 as such.\n- Reconcile `docs/plan/20-architecture.md` section 3.7 (Paper Matcher components) and the C11 row with the shipped module layout.\n- Ensure `docs/plan/22-api-openapi.yaml` contains the endpoints added by this epic (`POST /exchange-accounts/{accountId}/paper-reset`, `GET /admin/parity`, the parity verification endpoint, `GET /admin/paper-fidelity`) with correct `x-rbac` and `x-idempotency` annotations, and that the contract tests pass.\n- Ensure `docs/plan/21-database-schema.md` reflects the `user_account_access` eligibility columns and any paper-ledger/parity-observation tables added, including the migration ids.\n- Update `docs/plan/14-screens-catalogue.md` and `docs/plan/15-component-catalogue.md` where the shipped SCR-074/075/079/099/122/137 and CMP-074/075/139 behaviour differs from the written entry.\n- Amend `docs/plan/27-adrs/ADR-0016-demo-live-parity.md` with any decision made during implementation, and file a new ADR if a genuinely new architectural decision was taken.\n- Add the E38 changelog fragments and confirm `docs/plan/32-risk-register.md` reflects R12's current status given the divergence job's first results.",
   oos="- Rewriting documents that did not diverge - this is reconciliation, not a documentation project.\n- Producing user-facing help documentation.",
   ac="```gherkin\nScenario: Normative sections match the code\n  Given docs/plan/24-internal-schemas.md section 12\n  When compared field by field against the shipped FillModelConfig and matcher behaviour\n  Then every divergence is either corrected in the doc or justified inline as a deliberate deviation\n\nScenario: New endpoints are in the contract\n  Given the endpoints added by this epic\n  When the contract tests run\n  Then each is present in the OpenAPI document with correct RBAC and idempotency annotations, and the tests pass\n\nScenario: Screens and components reflect what shipped\n  Given the E38 screens and components\n  When their catalogue entries are reviewed against the build\n  Then any behavioural difference is reflected in the entry\n\nScenario: Decisions are recorded as ADRs\n  Given any architectural decision taken during E38 implementation\n  When this ticket completes\n  Then it is recorded in an ADR rather than living only in a pull-request discussion\n```",
   tech="- Do this as one pass at the end of the epic rather than piecemeal, so the reviewer sees the whole picture; but file it as a blocking item for the epic's Done so it cannot be quietly skipped.\n- Where code and doc disagree and the code is right, change the doc; where the doc is right, file a Bug against the code rather than weakening the doc to match.",
   test="- Contract tests (`make contracts`: `openapi_structural`, `ref_closure`, `rbac_coverage`, `error_registry_single_source`, `enum_parity_environment`) must pass after the changes.\n- A reviewer independently spot-checks three reconciled claims against the code.",
   sec="- The security program references (SR-040a in particular) must still accurately describe the implemented control; a doc that overstates a control is a security problem because later work will rely on it.",
   a11y="N/A - documentation.",
   perf="- Record the measured numbers from E38-Q03 into the performance standard's tracking section so budgets are backed by observed values rather than estimates.",
   obs="- Ensure the metrics and audit events E38 added are listed in the observability documentation, so operators know what exists.",
   dod="- [ ] All listed documents reviewed and reconciled, with a summary of changes on the ticket.\n- [ ] `make contracts` green.\n- [ ] ADR-0016 amended or a new ADR filed for any implementation-time decision.\n- [ ] Changelog fragments present.\n- [ ] Reviewed by the Architect.\n- [ ] `docs/plan/32-risk-register.md` updated with R12's status given the first divergence results.",
   deps="- `blocked_by: E38-S03`, `E38-S08`, `E38-T03` - the implementations whose final behaviour is being documented.",
   branch="`chore/e38-doc-reconcile`; PR size: docs-only.",
   refs="- `docs/plan/02-definition-of-ready-done.md` section 2.2\n- `docs/plan/24-internal-schemas.md` section 12, section 19 contract tests\n- `docs/plan/20-architecture.md` section 3.7\n- `docs/plan/27-adrs/`"))
